const PUBLICAS = ['id', 'fecha', 'contacto', 'empresa', 'provincia', 'zona', 'comercial', 'sector', 'producto', 'volumen',
  'plazo', 'puntos', 'temperatura', 'estado', 'llamar_antes', 'nota', 'decidido_en'];

// Devuelve los leads de ejemplo (comunes a todos, de solo lectura) y debajo los que ha enviado el visitante,
// en el orden en que los envió y marcados como suyos. Nunca expone el sid.
const q = $('Listar leads').first().json.query ?? {};
const sid = /^[a-f0-9]{32}$/.test(String(q.sid ?? '')) ? String(q.sid) : null;
const todas = $input.all().map((i) => i.json);
const publica = (r) => {
  const f = { tuya: r.sid !== 'demo' };
  for (const k of PUBLICAS) f[k] = r[k];
  return f;
};
const demo = todas.filter((r) => r.sid === 'demo').sort((a, b) => String(a.fecha).localeCompare(String(b.fecha)));
const propias = sid === null ? [] : todas
  .filter((r) => r.sid === sid)
  .sort((a, b) => Number(a.creado_ms) - Number(b.creado_ms));
return [{ json: { filas: demo.concat(propias).map(publica) } }];

// Reglas fijas de puntuación (sin IA) y reparto por zonas. Datos inventados.
const PRODUCTOS = { 'Perfiles para pladur': 40, 'Chapa perfilada para cubiertas': 40, 'Fleje de acero': 30, 'Corte a medida': 25, 'Otro producto': 0 };
const VOLUMENES = { 'Menos de 1.000 m al mes': 5, 'De 1.000 a 10.000 m al mes': 20, 'Más de 10.000 m al mes': 30 };
const PLAZOS = { 'Urgente (menos de 2 semanas)': 20, 'Este trimestre': 12, 'Solo pido información': 3 };
const SECTORES = { 'Construcción': 10, 'Estructuras metálicas': 10, 'Naves agrícolas': 8, 'Distribución de materiales': 8, 'Otro': 4 };
const ZONAS = {
  Norte: { comercial: 'Iker Zubia', provincias: ['Asturias', 'Bizkaia', 'Cantabria', 'Gipuzkoa', 'La Rioja', 'Navarra'] },
  Este: { comercial: 'Laia Puig', provincias: ['Barcelona', 'Castellón', 'Tarragona', 'Valencia', 'Zaragoza'] },
  'Centro y Sur': { comercial: 'Javier Ortega', provincias: ['Córdoba', 'Madrid', 'Málaga', 'Sevilla', 'Toledo', 'Valladolid'] },
};
const zonaDe = (provincia) => Object.entries(ZONAS).find(([, z]) => z.provincias.includes(provincia));
const ABIERTOS = ['Nuevo', 'Recordatorio enviado'];

// Puntos de 0 a 100 y temperatura. Caliente: llamar en 24 h. Templado: en 3 días. Frío: al boletín, sin llamada.
function puntuar(l) {
  const desglose = [
    { criterio: 'Producto', valor: l.producto, puntos: PRODUCTOS[l.producto] },
    { criterio: 'Volumen', valor: l.volumen, puntos: VOLUMENES[l.volumen] },
    { criterio: 'Plazo', valor: l.plazo, puntos: PLAZOS[l.plazo] },
    { criterio: 'Sector', valor: l.sector, puntos: SECTORES[l.sector] },
  ];
  const puntos = desglose.reduce((a, d) => a + d.puntos, 0);
  const temperatura = l.producto === 'Otro producto' ? 'Fuera de catálogo' : puntos >= 70 ? 'Caliente' : puntos >= 40 ? 'Templado' : 'Frío';
  return { puntos, temperatura, desglose };
}
const estadoInicial = (t) => ({ Caliente: 'Nuevo', Templado: 'Nuevo', 'Frío': 'Boletín', 'Fuera de catálogo': 'Descartado' }[t]);
const horasParaLlamar = (t) => ({ Caliente: 24, Templado: 72 }[t] ?? 0);
const clave = (s) => String(s).toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/,?\s*s\.?\s*[la]\.?$/, '').replace(/[^a-z0-9]/g, '');

// Valida el formulario de contacto del visitante, puntúa el lead, se lo asigna al comercial de su zona
// y fija hasta cuándo hay que llamarle.
const b = $('Crear lead').first().json.body ?? {};
const todas = $input.all().map((i) => i.json).filter((r) => r.sid);
const fallo = (error, status = 400) => [{ json: { ok: false, status, error } }];

const sid = String(b.sid ?? '');
if (!/^[a-f0-9]{32}$/.test(sid)) return fallo('Identificador de sesión no válido');
const propias = todas.filter((r) => r.sid === sid);
const demo = todas.filter((r) => r.sid === 'demo');
if (propias.length >= 20) return fallo('Has llegado al máximo de 20 contactos de prueba. Se borran solos a las 2 horas.', 429);
if (todas.length - demo.length >= 400) return fallo('La demo está llena ahora mismo. Vuelve dentro de un rato.', 429);

const texto = (v, max) => String(v ?? '').replace(/[\u0000-\u001f\u007f]/g, ' ').trim().slice(0, max);
const contacto = texto(b.contacto, 40);
if (!contacto) return fallo('Nombre: escribe un nombre (vale uno inventado)');
const empresa = texto(b.empresa, 60);
if (!empresa) return fallo('Empresa: escribe un nombre (vale uno inventado)');
const zona = zonaDe(b.provincia);
if (!zona) return fallo('Provincia: elige una de la lista');
if (!(b.sector in SECTORES)) return fallo('Sector: elige uno de la lista');
if (!(b.producto in PRODUCTOS)) return fallo('Producto: elige uno de la lista');
if (!(b.volumen in VOLUMENES)) return fallo('Volumen: elige uno de la lista');
if (!(b.plazo in PLAZOS)) return fallo('Plazo: elige uno de la lista');
const mensaje = texto(b.mensaje, 300);

const p = puntuar(b);
const ahora = $now.setZone('Europe/Madrid');
const horas = horasParaLlamar(p.temperatura);
// Si la empresa ya tiene un lead abierto, el nuevo va al mismo comercial y se avisa de que es repetido.
const previo = demo.concat(propias).find((r) => clave(r.empresa) === clave(empresa) && ABIERTOS.includes(r.estado));
const comercial = previo ? previo.comercial : zona[1].comercial;
const nota = previo ? `Ya escribió el ${String(previo.fecha).slice(0, 10)}: lo lleva ${previo.comercial}` : '';

return [{ json: { ok: true, fila: {
  sid, fecha: ahora.toFormat('yyyy-MM-dd HH:mm'), contacto, empresa, provincia: b.provincia, zona: zona[0], comercial,
  sector: b.sector, producto: b.producto, volumen: b.volumen, plazo: b.plazo, mensaje,
  puntos: p.puntos, temperatura: p.temperatura, desglose: JSON.stringify(p.desglose),
  estado: estadoInicial(p.temperatura), llamar_antes: horas ? ahora.plus({ hours: horas }).toFormat('yyyy-MM-dd HH:mm') : '',
  nota, decidido_en: '', creado_ms: Date.now(),
} } }];

const PUBLICAS = ['id', 'fecha', 'contacto', 'empresa', 'provincia', 'zona', 'comercial', 'sector', 'producto', 'volumen',
  'plazo', 'puntos', 'temperatura', 'estado', 'llamar_antes', 'nota', 'decidido_en'];

// Devuelve el lead registrado y los correos que mandaría el flujo real: la respuesta automática al cliente
// y el aviso interno (al comercial si hay que llamar, a marketing si va al boletín). En la demo no sale ninguno.
const r = $('Guardar lead demo').first().json;
const lead = { tuya: true };
for (const k of PUBLICAS) lead[k] = r[k];
const desglose = JSON.parse(r.desglose || '[]');

const esc = (s) => String(s ?? '').replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const cuando = (s) => { const [d, h] = String(s).split(' '); return `${d.split('-').reverse().join('/')} a las ${h}`; };
const nombre = esc(r.contacto.split(' ')[0]);
const caja = (s) => `<div style="font-family:Arial,sans-serif;font-size:14px;color:#1d2430">${s}
<p style="color:#5b6676">Mensaje automático de la demo de marketing. Todos los datos son inventados.</p></div>`;

const respuesta = {
  Caliente: `<p>Hola ${nombre}:</p><p>Gracias por escribirnos. Hemos recibido su consulta sobre <b>${esc(r.producto.toLowerCase())}</b>.</p>
<p>${esc(r.comercial)}, su comercial para la zona ${esc(r.zona)}, le llamará antes del <b>${cuando(r.llamar_antes)}</b> para preparar la oferta.</p>`,
  Templado: `<p>Hola ${nombre}:</p><p>Gracias por escribirnos. Le adjuntamos el catálogo de <b>${esc(r.producto.toLowerCase())}</b> con medidas y plazos de entrega.</p>
<p>${esc(r.comercial)}, su comercial para la zona ${esc(r.zona)}, se pondrá en contacto con usted en los próximos días.</p>`,
  'Frío': `<p>Hola ${nombre}:</p><p>Gracias por escribirnos. Le adjuntamos nuestro catálogo general.</p>
<p>Si más adelante tiene un pedido en firme, conteste a este correo y le pasamos con su comercial.</p>`,
  'Fuera de catálogo': `<p>Hola ${nombre}:</p><p>Gracias por escribirnos. Lo que nos pide no está entre lo que fabricamos: trabajamos perfiles, chapa perfilada, fleje y corte a medida de acero.</p>
<p>Si necesita alguno de estos productos, estaremos encantados de ayudarle.</p>`,
}[r.temperatura];
const cliente = { de: 'Ventas', para: `${r.contacto} · ${r.empresa}`, asunto: `Hemos recibido su consulta, ${r.contacto.split(' ')[0]}`, html: caja(respuesta + '<p>Un saludo,<br>Departamento comercial</p>') };

const fila = (k, v) => `<tr><td style="padding:3px 12px 3px 0;color:#555">${k}</td><td style="padding:3px 0"><b>${v}</b></td></tr>`;
const datos = `<table>
${fila('Empresa', `${esc(r.empresa)} · ${esc(r.provincia)}`)}
${fila('Contacto', esc(r.contacto))}
${fila('Sector', esc(r.sector))}
${fila('Pide', `${esc(r.producto)} · ${esc(r.volumen)} · ${esc(r.plazo.toLowerCase())}`)}
${r.mensaje ? fila('Mensaje', esc(r.mensaje)) : ''}
${r.nota ? fila('Ojo', esc(r.nota)) : ''}
</table>
<p style="margin:14px 0 4px"><b>Puntuación: ${r.puntos} de 100 (${esc(r.temperatura.toLowerCase())})</b></p>
<table>${desglose.map((d) => `<tr><td style="padding:2px 12px 2px 0;color:#555">${esc(d.criterio)}</td><td style="padding:2px 12px 2px 0">${esc(d.valor)}</td><td style="padding:2px 0;text-align:right"><b>+${d.puntos}</b></td></tr>`).join('')}</table>`;

let interno = null;
if (r.estado === 'Nuevo') {
  const caliente = r.temperatura === 'Caliente';
  interno = {
    de: 'CRM', para: r.comercial,
    asunto: `${caliente ? '⚠ Lead caliente' : 'Lead nuevo'} · ${r.empresa} · llamar antes del ${cuando(r.llamar_antes)}`,
    html: caja(`<p>${caliente ? '<b>Lead caliente:</b> llama hoy si puedes.' : 'Lead templado: llama esta semana.'} Si no lo marcas como contactado antes del ${cuando(r.llamar_antes)}, te llegará un recordatorio y se avisará a dirección comercial.</p>${datos}`),
  };
} else if (r.estado === 'Boletín') {
  interno = { de: 'CRM', para: 'Marketing', asunto: `Lead frío al boletín · ${r.empresa} · ${r.puntos} puntos`,
    html: caja(`<p>No llega a 40 puntos: no se asigna llamada. Queda en la lista del boletín mensual.</p>${datos}`) };
}

return [{ json: { ok: true, lead, correos: interno ? [cliente, interno] : [cliente] } }];

// Comprueba que el lead existe, es del visitante y sigue abierto, y calcula el estado nuevo.
const b = $('Decidir lead').first().json.body ?? {};
const fallo = (error, status = 400) => [{ json: { ok: false, status, error } }];

const sid = String(b.sid ?? '');
if (!/^[a-f0-9]{32}$/.test(sid)) return fallo('Identificador de sesión no válido');
const id = Number(b.id);
if (!Number.isInteger(id) || id < 1) return fallo('Lead no válido');
if (!['contactado', 'descartar'].includes(b.decision)) return fallo('Decisión no válida');

const r = $input.all().map((i) => i.json).find((x) => x.sid === sid && Number(x.id) === id);
if (!r) return fallo('No se encuentra ese contacto. Los de prueba se borran a las 2 horas; los de ejemplo no se pueden cambiar.', 404);
if (!['Nuevo', 'Recordatorio enviado'].includes(r.estado)) return fallo(`Ese lead ya está ${String(r.estado).toLowerCase()}.`, 409);

const estado = b.decision === 'contactado' ? 'Contactado' : 'Descartado';
const decidido_en = $now.setZone('Europe/Madrid').toFormat('yyyy-MM-dd HH:mm');
return [{ json: { ok: true, id, sid, estado, decidido_en, fila: { ...r, estado, decidido_en } } }];

const PUBLICAS = ['id', 'fecha', 'contacto', 'empresa', 'provincia', 'zona', 'comercial', 'sector', 'producto', 'volumen',
  'plazo', 'puntos', 'temperatura', 'estado', 'llamar_antes', 'nota', 'decidido_en'];

// Devuelve el lead ya decidido y la nota que el CRM deja a dirección comercial.
const r = $('Comprobar decisión').first().json.fila;
const lead = { tuya: true };
for (const k of PUBLICAS) lead[k] = r[k];

const esc = (s) => String(s ?? '').replace(/[&<>"]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
const html = `<div style="font-family:Arial,sans-serif;font-size:14px;color:#1d2430">
<p>${esc(r.comercial)} ha marcado el lead de <b>${esc(r.empresa)}</b> como <b>${esc(r.estado.toLowerCase())}</b> el ${esc(r.decidido_en.slice(8, 10))}/${esc(r.decidido_en.slice(5, 7))} a las ${esc(r.decidido_en.slice(11))}.</p>
<p>${r.estado === 'Contactado' ? 'El recordatorio queda cancelado. La oportunidad pasa a la lista de ofertas en preparación.' : 'El recordatorio queda cancelado y el contacto pasa a la lista del boletín.'}</p>
<p style="color:#5b6676">Mensaje automático de la demo de marketing. Todos los datos son inventados.</p></div>`;

return [{ json: { ok: true, lead, correo: { de: 'CRM', para: 'Dirección comercial', asunto: `Lead ${r.estado.toLowerCase()} · ${r.empresa} · ${r.comercial}`, html } } }];
